// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        // Admissible domain: any positive balance held by c.
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(c), amount);
        // The owner (this test contract, a non-payable contract) calls withdrawAll.
        // The reference performs a real transfer of address(c).balance to msg.sender,
        // which must fail against a non-payable recipient => withdrawAll reverts.
        // The mutant sends nothing, so no transfer is attempted => it succeeds.
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
